<?php declare(strict_types=1);
use Kulturhus\Verein\TaxCatalog;
use Kulturhus\Verein\Web\TaxCatalogueForm;
$taxCatalogueTab='tax-accounts';$canEditTaxAccounts=$canFinance&&$finance->canWrite();
if(!$canFinance){require __DIR__.'/tax-catalogue-context.php';return;}
if(($_GET['catalog']??null)==='1'){require __DIR__.'/../../Catalog/catalog-import.php';return;}
if(!(require __DIR__.'/tax-catalogue-context.php'))return;
$taxAccounts=$finance->taxAccounts();$search=$taxCatalogueQuery['q'];$group=$taxCatalogueQuery['group'];$active=$taxCatalogueQuery['active'];
$filtered=array_filter($taxAccounts,static fn(array $a):bool=>($search===''||mb_stripos($a['code'].' '.$a['name'].(in_array($a['code'],['40450','40500','40550','40600','40650','40700'],true)?' Spende '.$taxCatalogueText('Spende'):''),$search,0,'UTF-8')!==false)&&($group===''||$a['category']===$group)&&($active===''||(string)$a['active']===$active));
$pages=max(1,(int)ceil(count($filtered)/50));
try{$page=TaxCatalogueForm::page($taxCatalogueQuery,$pages);}catch(DomainException $taxCatalogueFailure){require __DIR__.'/tax-catalogue-error.php';return;}
$shown=array_slice($filtered,($page-1)*50,50);$catalogStatus=TaxCatalog::sourceStatus();
?>
<div data-tax-catalogue><div class="page-heading"><h1><?=e($taxCatalogueText('Steuerkontenliste'))?></h1><?php if($canEditTaxAccounts):?><a class="btn btn-outline theme-secondary" href="?view=settings&amp;tab=tax-accounts&amp;catalog=1"><?=e($taxCatalogueText('Kontenplan aktualisieren'))?></a><?php endif?></div>
<div class="content"><section class="card"><div class="section-heading"><div><h2><?=e($taxCatalogueText('Kontenplan für unseren Verein · {year}',['year'=>TaxCatalog::YEAR]))?></h2><p><?=e($taxCatalogueText('{count} Einzel- und Hauptkonten aus dem SKR42-Jahreskatalog; reservierte Bereiche sind inaktiv. Eigene fünfstellige Konten und Unterkonten können ergänzt werden.',['count'=>count(TaxCatalog::accounts())]))?></p></div><a class="btn btn-outline theme-secondary" href="?view=finance&amp;tab=reports"><?=e($taxCatalogueText('Auswertungen'))?></a></div>
<form method="get" class="filter-panel"><?=hidden('view','settings').hidden('tab','tax-accounts')?><label><?=e($taxCatalogueText('Suche'))?><input class="form-control" type="search" name="q" maxlength="1000" value="<?=e($search)?>" placeholder="<?=e($taxCatalogueText('Kontonummer oder Bezeichnung'))?>"></label><label><?=e($taxCatalogueText('Kategorie'))?><select class="form-control" name="group"><option value=""><?=e($taxCatalogueText('Alle Kategorien'))?></option><?php foreach(TaxCatalog::GROUPS as$key=>$name):?><option value="<?=e($key)?>" <?=$group===$key?'selected':''?>><?=e($taxCatalogueText($name))?></option><?php endforeach?></select></label><label><?=e($taxCatalogueText('Status'))?><select class="form-control" name="active"><?php foreach(['1'=>'Aktiv','0'=>'Inaktiv',''=>'Alle']as$key=>$name):?><option value="<?=e($key)?>" <?=$active===(string)$key?'selected':''?>><?=e($taxCatalogueText($name))?></option><?php endforeach?></select></label><button class="btn btn-solid theme-primary"><?=e($taxCatalogueText('Anwenden'))?></button></form>
<p><?=e($taxCatalogueText('{count} Konten · Seite {page} / {pages}',['count'=>count($filtered),'page'=>$page,'pages'=>$pages]))?></p><div class="table-scroll" tabindex="0"><table class="table"><thead><tr><?php foreach(['Nummer','Bezeichnung','Kategorie',$canEditTaxAccounts?'Status / Bearbeiten':'Status']as$label):?><th><?=e($taxCatalogueText($label))?></th><?php endforeach?></tr></thead><tbody>
<?php foreach($shown as$a):?><tr data-tax-account="<?=e($a['code'])?>"><td><?=e($a['code'])?></td><td><?=e($a['name'])?><small class="block muted"><?=e($a['custom']?$taxCatalogueText('Vereinseigen'):$taxCatalogueText('DATEV · S. {page} · {function}',['page'=>$a['page']??'–','function'=>$a['function']?:$taxCatalogueText('ohne Automatik')]))?><?=($a['blocked']??false)?' · '.e($taxCatalogueText('für neue Kontierungen gesperrt')):''?></small></td><td><?=e($taxCatalogueText(TaxCatalog::GROUPS[$a['category']]))?></td><td><?php if($canEditTaxAccounts):?><details><summary><?=e($taxCatalogueText($a['active']?'Aktiv':'Inaktiv'))?> · <?=e($taxCatalogueText('Bearbeiten'))?></summary><form method="post" action="<?=e(url(array_replace($taxCatalogueQuery,['account'=>$a['code']])))?>"><?=csrf().hidden('action','save-tax-account').hidden('code',$a['code']).hidden('version',$a['version'])?><label><?=e($taxCatalogueText('Bezeichnung'))?><input class="form-control" name="name" required maxlength="200" value="<?=e($a['name'])?>"></label><label class="check"><input class="check" type="checkbox" name="active" value="1" <?=$a['active']?'checked':''?>> <?=e($taxCatalogueText('Für neue Kontierungen verwenden'))?></label><button class="btn btn-solid theme-primary"><?=e($taxCatalogueText('Speichern'))?></button></form></details><?php else:?><span><?=e($taxCatalogueText($a['active']?'Aktiv':'Inaktiv'))?></span><?php endif?></td></tr><?php endforeach?>
<?php if(!$filtered):?><tr><td colspan="4"><?=e($taxCatalogueText('Keine Konten für diesen Filter.'))?></td></tr><?php endif?></tbody></table></div>
<nav class="actions" aria-label="<?=e($taxCatalogueText('Kontenseiten'))?>"><?php foreach([-1=>'← Zurück',1=>'Weiter →']as$d=>$label):if($page+$d<1||$page+$d>$pages)continue;?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'settings','tab'=>'tax-accounts','q'=>$search,'group'=>$group,'active'=>$active,'page'=>$page+$d]))?>"><?=e($taxCatalogueText($label))?></a><?php endforeach?></nav></section>
<?php if($canEditTaxAccounts):?><section class="card"><h2><?=e($taxCatalogueText('Eigenes Steuerkonto / Unterkonto'))?></h2><form method="post" action="<?=e(url(array_diff_key($taxCatalogueQuery,['account'=>true])))?>"><?=csrf().hidden('action','save-tax-account').hidden('version','0').hidden('create_only','1')?><div class="form-grid"><label><?=e($taxCatalogueText('Kontonummer'))?><input class="form-control" name="code" required pattern="[0-79][0-9]{4}" maxlength="5" placeholder="40401"></label><label><?=e($taxCatalogueText('Bezeichnung'))?><input class="form-control" name="name" required maxlength="200"></label></div><label class="check"><input class="check" type="checkbox" name="active" value="1" checked> <?=e($taxCatalogueText('Für neue Kontierungen aktivieren'))?></label><button class="btn btn-solid theme-primary"><?=e($taxCatalogueText('Steuerkonto anlegen'))?></button></form><p class="muted"><?=e($taxCatalogueText('Eigene Konten erhalten eine Kategorie anhand der ersten Ziffer. Ihre steuerliche Verwendbarkeit wird nicht automatisch bestätigt. Gespeicherte Belegpositionen behalten ihre bisherige Bezeichnung, auch wenn ein Konto umbenannt oder deaktiviert wird.'))?></p></section><?php endif?>
<section class="card"><h2><?=e($taxCatalogueText('Jahresstände des Kontenplans'))?></h2><p><?=e($taxCatalogueText('Aktueller Stand:'))?> <strong>SKR42 <?=(int)$catalogStatus['year']?></strong>.</p><p><?=e($taxCatalogueText('Für ältere Belege bleibt der bisherige Jahresstand erhalten. Neue Kontenpläne werden zentral geprüft und mit einer Aktualisierung bereitgestellt.'))?></p><p><?php foreach(TaxCatalog::YEARS as$index=>$year):$status=TaxCatalog::sourceStatus($year);?><?=$index?' · ':''?><a href="<?=e($status['source'])?>" target="_blank" rel="noreferrer"><?=e($taxCatalogueText('DATEV-Kontenplan {year}',['year'=>$year]))?></a><?php endforeach?></p><p><a href="?view=settings&amp;tab=booking-keys"><?=e($taxCatalogueText('Steuer- und Buchungsschlüssel'))?></a></p></section></div></div>
